SELECT r.id AS id, r.patient_id AS patientId, r.registration_status AS registrationStatus, r.create_time AS createTime, p.real_name AS patientName, , COALESCE(dept.department_name, s.department_name) AS departmentName, s.schedule_date AS scheduleDate, COALESCE(d.real_name, s.doctor_name) AS doctorName, CASE WHEN s.is_morning = 1 THEN '上午' WHEN s.is_afternoon = 1 THEN '下午' END AS timePeriod FROM registration r INNER JOIN patient_attendant p ON r.patient_id = p.id INNER JOIN schedule s ON r.schedule_id = s.id LEFT JOIN doctor_detail d ON r.doctor_id = d.id LEFT JOIN sub_department dept ON d.sub_department_id = dept.id WHERE p.system_user_id = #{userId} and r.is_deleted = 0 and p.is_deleted =0
AND s.schedule_date >= #{registrationCondition.startDate}
AND s.schedule_date <= #{registrationCondition.endDate}
AND r.registration_status = #{registrationCondition.registrationStatus}
ORDER BY s.schedule_date DESC

SELECT r.id AS id, r.patient_id AS patientId, r.registration_status AS registrationStatus, r.create_time AS createTime, p.real_name AS patientName, , d.real_name AS doctorName, dept.department_name AS departmentName, s.schedule_date AS scheduleDate, CASE WHEN s.is_morning = 1 THEN '上午' WHEN s.is_afternoon = 1 THEN '下午' END AS timePeriod FROM registration r JOIN patient_attendant p ON r.patient_id = p.id JOIN schedule s ON r.schedule_id = s.id JOIN doctor_detail d ON s.doctor_id = d.id JOIN sub_department dept ON d.sub_department_id = dept.id where r.schedule_id = #{scheduleId}
AND r.registration_status = #{registrationCondition.registrationStatus}
AND r.registration_status IN (2,3,5,6,7)
AND r.registration_status IN (2,3,5,6,7)
AND r.is_deleted = 0 and p.is_deleted = 0 and s.is_deleted = 0 and d.is_deleted = 0 ORDER BY r.id ASC

SELECT r.id AS id, r.patient_id AS patientId, r.registration_status AS registrationStatus, r.create_time AS createTime, p.real_name AS patientName, , d.real_name AS doctorName, dept.department_name AS departmentName, s.schedule_date AS scheduleDate, case when s.is_morning = 1 then '上午' when s.is_afternoon = 1 then '下午' end AS timePeriod FROM registration r JOIN patient_attendant p ON r.patient_id = p.id JOIN doctor_detail d ON r.doctor_id = d.id JOIN sub_department dept ON d.sub_department_id = dept.id JOIN schedule s ON r.schedule_id = s.id WHERE r.doctor_id = #{doctorId} AND r.is_deleted = 0 AND p.is_deleted = 0 AND d.is_deleted = 0
AND s.schedule_date >= #{registrationCondition.startDate}
AND s.schedule_date <= #{registrationCondition.endDate}
AND r.registration_status = #{registrationCondition.registrationStatus}
AND r.registration_status IN (2,3,4,5,6,7,8)
AND r.registration_status IN (2,3,4,5,6,7,8)
